    throw new Error("advanceVok1: Vok must be in state 'nim'");
  }
  return { ...world, vok: "pex" };
}

/**
 * advanceVok2 (= O2): Vok: pex -> dor, requires Zef === "pex" AND Osk === "pex"
 * (D1: O2 depends on E2)
 * (D2: O2 depends on E5 — Invariant I4: Vok=dor → Osk=pex, explicit cross-chain)
 */
export function advanceVok2(world: WorldState): WorldState {
  if (world.vok !== "pex") {
    throw new Error("advanceVok2: Vok must be in state 'pex'");
  }
  if (world.zef !== "pex") {
    throw new Error("advanceVok2: requires Zef to be 'pex'");
  }
  if (world.osk !== "pex") {
    throw new Error("advanceVok2: requires Osk to be 'pex'");
  }
  return { ...world, vok: "dor" };
}

/**
 * forceAdvanceVok (= O12): Vok: nim -> dor (直接ジャンプ)
 * requires Tal === "pex" AND Osk === "pex"
 *
 * Invariant I1（Vok=dor ならば Tal=pex）を保つため Tal=pex が必要。
 * Invariant I4（Vok=dor ならば Osk=pex）を保つため Osk=pex が必要。
 */
export function forceAdvanceVok(world: WorldState): WorldState {
  if (world.vok !== "nim") {
    throw new Error("forceAdvanceVok: Vok must be in state 'nim'");
  }
  if (world.tal !== "pex") {
    throw new Error("forceAdvanceVok: requires Tal to be 'pex' (Invariant I1)");
  }
  if (world.osk !== "pex") {
    throw new Error("forceAdvanceVok: requires Osk to be 'pex' (Invariant I4)");
  }
  return { ...world, vok: "dor" };
}

